INSERT INTO `des_designer` (`designer_id`, `user_id`, `designer_name`, `avatar`, `gender`, `birth_date`, `phone`, `email`, `description`, `profession`, `skill_tags`, `work_years`, `work_status`, `location`, `school_id`, `enterprise_id`, `graduation_date`, `join_date`, `portfolio_url`, `social_links`, `status`, `create_time`, `update_time`) VALUES
(1, 1, '陈雨晴', 'https://api.dicebear.com/9.x/shapes/svg?seed=chenyu', '1', '1995-06-15', '13812345678', 'chenyu@example.com', '拥有 5 年 UI/UX 设计经验，专注于移动应用和 Web 产品的用户体验设计。擅长用户研究、交互设计和视觉设计，能够从用户需求出发，打造直观易用的产品界面。曾主导腾讯多个核心产品的设计工作，包括社交、游戏和企业应用等领域。精通用户研究方法，具备敏锐的用户洞察力和优秀的设计执行力。', 'UI_UX_DESIGNER', '["figma", "user_research", "interaction_design", "prototype_design", "design_system"]', 5, 'EMPLOYED', '深圳市南山区', 1, 1, '2018-06-30', '2022-03-01', 'https://chenyudesign.com', '{"dribbble": "https://dribbble.com/chenyu", "behance": "https://behance.net/chenyu", "linkedin": "https://linkedin.com/in/chenyu"}', '0', '2023-01-01 00:00:00', '2023-12-01 00:00:00'),
(2, 2, '林子豪', 'https://api.dicebear.com/9.x/shapes/svg?seed=linzihao', '0', '1990-03-22', '13923456789', 'linzihao@example.com', '专业视觉设计师，专注于品牌设计和视觉传达。拥有丰富的品牌标识设计经验，善于通过视觉语言传达品牌价值。曾为多家知名企业设计品牌形象，包括LOGO设计、VI系统、包装设计等。在色彩搭配和字体设计方面有独到见解，作品风格简约而富有张力。', 'VISUAL_DESIGNER', '["photoshop", "illustrator", "brand_design", "typography", "visual_design"]', 7, 'EMPLOYED', '上海市浦东新区', NULL, 2, NULL, NULL, 'https://linzihaodesign.com', '{"instagram": "https://instagram.com/linzihao", "behance": "https://behance.net/linzihao"}', '0', '2022-06-01 00:00:00', '2023-12-01 00:00:00'),
(3, 3, '王梦琪', 'https://api.dicebear.com/9.x/shapes/svg?seed=wangmengqi', '1', '1992-08-10', '13634567890', 'wangmengqi@example.com', '3D 动画设计师，专注于三维建模和动画制作。拥有丰富的影视和游戏行业经验，擅长角色建模、场景设计和动画制作。作品曾在多个国际动画节获奖，具备扎实的美术功底和前沿的技术实力。', 'THREE_D_DESIGNER', '["blender", "cinema_4d", "animation_design", "character_design", "visual_design"]', 4, 'FREELANCER', '北京市朝阳区', NULL, NULL, NULL, NULL, 'https://wangmengqi3d.com', '{"artstation": "https://artstation.com/wangmengqi"}', '0', '2023-03-01 00:00:00', '2023-12-01 00:00:00'),
(4, 4, '赵明宇', 'https://api.dicebear.com/9.x/shapes/svg?seed=zhaomingyu', '0', '1991-12-05', '13745678901', 'zhaomingyu@example.com', '产品设计师，专注于数字产品的用户体验设计和产品策略。拥有深厚的产品思维和用户洞察能力，善于从商业目标出发，设计既美观又实用的产品界面。在B端产品设计方面经验丰富，曾主导多个企业级产品的设计工作。', 'PRODUCT_DESIGNER', '["sketch", "prototype_design", "user_experience", "design_system", "user_research"]', 6, 'EMPLOYED', '杭州市西湖区', NULL, 3, NULL, NULL, 'https://zhaomingyu.design', '{"medium": "https://medium.com/@zhaomingyu"}', '0', '2022-09-01 00:00:00', '2023-12-01 00:00:00'),
(5, 5, '李思雨', 'https://api.dicebear.com/9.x/shapes/svg?seed=lisiyu', '1', '1996-04-18', '13856789012', 'lisiyu@example.com', '交互设计师，专注于数字产品的交互体验设计。具备丰富的用户研究经验和交互设计技能，善于通过原型设计和用户测试验证设计方案。曾参与多个大型互联网产品的交互设计工作，在移动端交互设计方面有深入研究。', 'INTERACTION_DESIGNER', '["figma", "prototype_design", "user_research", "wireframing", "user_testing"]', 3, 'EMPLOYED', '成都市高新区', 2, NULL, '2020-06-30', '2020-07-15', 'https://lisiyu.design', '{"dribbble": "https://dribbble.com/lisiyu", "github": "https://github.com/lisiyu"}', '0', '2023-05-01 00:00:00', '2023-12-01 00:00:00'),
(6, 6, '张伟强', 'https://api.dicebear.com/9.x/shapes/svg?seed=zhangweiqiang', '0', '1989-09-30', '13967890123', 'zhangweiqiang@example.com', '品牌设计师，专注于企业品牌形象设计和视觉识别系统构建。拥有多年品牌设计经验，为众多知名企业提供过品牌设计服务。擅长将品牌理念转化为视觉符号，在LOGO设计、VI系统、包装设计等领域具备专业能力。', 'BRAND_DESIGNER', '["illustrator", "photoshop", "brand_design", "typography", "color_theory"]', 8, 'FREELANCER', '广州市天河区', NULL, NULL, NULL, NULL, 'https://zhangweiqiang.design', '{"behance": "https://behance.net/zhangweiqiang", "instagram": "https://instagram.com/zhangweiqiang"}', '0', '2022-01-01 00:00:00', '2023-12-01 00:00:00'),
(7, 7, '刘小雅', 'https://api.dicebear.com/9.x/shapes/svg?seed=liuxiaoya', '1', '1994-07-12', '13078901234', 'liuxiaoya@example.com', '动效设计师，专注于数字媒体动画和视觉特效设计。具备丰富的动效制作经验，善于运用各种动效技术创造引人入胜的视觉体验。作品涵盖品牌动画、产品演示动画、UI动效等多个领域，在创意表达和技术实现方面都有出色表现。', 'MOTION_DESIGNER', '["after_effects", "cinema_4d", "animation_design", "visual_design", "illustration"]', 4, 'EMPLOYED', '武汉市洪山区', NULL, 4, NULL, NULL, 'https://liuxiaoya.motion', '{"vimeo": "https://vimeo.com/liuxiaoya", "behance": "https://behance.net/liuxiaoya"}', '0', '2023-02-01 00:00:00', '2023-12-01 00:00:00'),
(8, 8, '孙志华', 'https://api.dicebear.com/9.x/shapes/svg?seed=sunzhihua', '0', '1990-11-28', '13189012345', 'sunzhihua@example.com', '插画师，专注于商业插画和角色设计。具备扎实的美术功底和独特的创作风格，作品风格多样，能够根据不同项目需求调整创作方向。在儿童绘本、品牌插画、游戏角色设计等领域有丰富经验，作品多次获得业内认可。', 'ILLUSTRATOR', '["illustrator", "photoshop", "illustration", "character_design", "visual_design"]', 6, 'FREELANCER', '西安市雁塔区', NULL, NULL, NULL, NULL, 'https://sunzhihua.art', '{"instagram": "https://instagram.com/sunzhihua", "artstation": "https://artstation.com/sunzhihua"}', '0', '2022-08-01 00:00:00', '2023-12-01 00:00:00'),
(9, 9, '周雅琪', 'https://api.dicebear.com/9.x/shapes/svg?seed=zhouyaqi', '1', '1993-05-14', '13290123456', 'zhouyaqi@example.com', '平面设计师，专注于印刷品设计和数字媒体设计。在杂志排版、海报设计、宣传册制作等方面有丰富经验。善于运用色彩和排版创造视觉冲击力，作品风格现代简约，注重信息传达的清晰性和美观性。', 'GRAPHIC_DESIGNER', '["photoshop", "illustrator", "graphic_design", "typography", "layout_design"]', 5, 'EMPLOYED', '南京市鼓楼区', NULL, 5, NULL, NULL, 'https://zhouyaqi.design', '{"behance": "https://behance.net/zhouyaqi", "pinterest": "https://pinterest.com/zhouyaqi"}', '0', '2022-11-01 00:00:00', '2023-12-01 00:00:00'),
(10, 10, '吴志强', 'https://api.dicebear.com/9.x/shapes/svg?seed=wuzhiqiang', '0', '1994-09-20', '13301234567', 'wuzhiqiang@example.com', 'UI设计师，专注于移动应用和Web界面的视觉设计。具备敏锐的视觉感知能力和优秀的设计执行力，善于将品牌元素融入界面设计中。在电商、金融、教育等多个行业有丰富的设计经验，作品注重用户体验和视觉美感的平衡。', 'UI_DESIGNER', '["figma", "sketch", "ui_design", "visual_design", "design_system"]', 4, 'EMPLOYED', '苏州市工业园区', NULL, 6, NULL, NULL, 'https://wuzhiqiang.design', '{"dribbble": "https://dribbble.com/wuzhiqiang", "linkedin": "https://linkedin.com/in/wuzhiqiang"}', '0', '2023-01-15 00:00:00', '2023-12-01 00:00:00'),
(11, 11, '林小雨', 'https://api.dicebear.com/9.x/shapes/svg?seed=linxiaoyu', '1', '1991-12-08', '13412345678', 'linxiaoyu@example.com', 'UX设计师，专注于用户体验研究和交互设计。具备深厚的用户研究背景，善于通过数据分析和用户访谈洞察用户需求。在复杂业务场景的UX设计方面有丰富经验，曾为多个大型企业级产品提供用户体验优化服务。', 'UX_DESIGNER', '["user_research", "prototype_design", "user_testing", "information_architecture", "wireframing"]', 6, 'EMPLOYED', '重庆市渝北区', NULL, 7, NULL, NULL, 'https://linxiaoyu.ux', '{"medium": "https://medium.com/@linxiaoyu", "linkedin": "https://linkedin.com/in/linxiaoyu"}', '0', '2022-07-01 00:00:00', '2023-12-01 00:00:00'),
(12, 12, '陈志明', 'https://api.dicebear.com/9.x/shapes/svg?seed=chenzhiming', '0', '1989-04-16', '13523456789', 'chenzhiming@example.com', '动效设计师，专注于数字媒体动画和视觉特效制作。具备丰富的影视后期制作经验，善于运用各种动效技术创造震撼的视觉体验。作品涵盖广告动画、产品演示、品牌宣传片等多个领域，在创意表达和技术实现方面都有出色表现。', 'MOTION_DESIGNER', '["after_effects", "cinema_4d", "motion_design", "animation", "visual_effects"]', 7, 'FREELANCER', '天津市和平区', NULL, NULL, NULL, NULL, 'https://chenzhiming.motion', '{"vimeo": "https://vimeo.com/chenzhiming", "instagram": "https://instagram.com/chenzhiming"}', '0', '2022-03-01 00:00:00', '2023-12-01 00:00:00'),
(13, 13, '黄雅婷', 'https://api.dicebear.com/9.x/shapes/svg?seed=huangyating', '1', '1992-07-25', '13634567890', 'huangyating@example.com', 'UI/UX设计师，专注于移动应用和Web产品的用户体验设计。具备深厚的用户研究背景和优秀的设计执行力，善于通过数据驱动的方法优化产品体验。在电商、社交、教育等多个领域有丰富经验，作品注重用户需求和商业目标的平衡。', 'UI_UX_DESIGNER', '["figma", "sketch", "user_research", "prototype_design", "design_system"]', 5, 'EMPLOYED', '厦门市思明区', NULL, 8, NULL, NULL, 'https://huangyating.design', '{"dribbble": "https://dribbble.com/huangyating", "linkedin": "https://linkedin.com/in/huangyating"}', '0', '2022-09-15 00:00:00', '2023-12-01 00:00:00'),
(14, 14, '杨志强', 'https://api.dicebear.com/9.x/shapes/svg?seed=yangzhiqiang', '0', '1988-11-12', '13745678901', 'yangzhiqiang@example.com', '品牌设计师，专注于企业品牌形象设计和视觉识别系统构建。拥有多年品牌设计经验，为众多知名企业提供过品牌设计服务。擅长将品牌理念转化为视觉符号，在LOGO设计、VI系统、品牌应用等方面具备专业能力。', 'BRAND_DESIGNER', '["illustrator", "photoshop", "brand_design", "typography", "visual_identity"]', 8, 'FREELANCER', '青岛市市南区', NULL, NULL, NULL, NULL, 'https://yangzhiqiang.brand', '{"behance": "https://behance.net/yangzhiqiang", "instagram": "https://instagram.com/yangzhiqiang"}', '0', '2021-12-01 00:00:00', '2023-12-01 00:00:00'),
(15, 15, '刘梦琪', 'https://api.dicebear.com/9.x/shapes/svg?seed=liumengqi', '1', '1991-03-18', '13856789012', 'liumengqi@example.com', '3D设计师，专注于三维建模和角色设计。具备扎实的美术功底和前沿的技术实力，在游戏美术、影视特效、产品展示等领域有丰富经验。擅长角色建模、场景设计和动画制作，作品风格独特，技术精湛。', 'THREE_D_DESIGNER', '["blender", "maya", "3d_modeling", "character_design", "animation_design"]', 6, 'EMPLOYED', '大连市中山区', NULL, 9, NULL, NULL, 'https://liumengqi.3d', '{"artstation": "https://artstation.com/liumengqi", "instagram": "https://instagram.com/liumengqi"}', '0', '2022-05-01 00:00:00', '2023-12-01 00:00:00'),
(16, 16, '张雅文', 'https://api.dicebear.com/9.x/shapes/svg?seed=zhangyawen', '1', '1995-08-30', '13967890123', 'zhangyawen@example.com', '产品设计师，专注于数字产品的用户体验设计和产品策略。具备深厚的产品思维和用户洞察能力，善于从商业目标出发，设计既美观又实用的产品界面。在B端产品设计方面经验丰富，曾主导多个企业级产品的设计工作。', 'PRODUCT_DESIGNER', '["sketch", "figma", "user_experience", "prototype_design", "design_system"]', 4, 'EMPLOYED', '无锡市滨湖区', NULL, 10, NULL, NULL, 'https://zhangyawen.product', '{"medium": "https://medium.com/@zhangyawen", "linkedin": "https://linkedin.com/in/zhangyawen"}', '0', '2023-02-01 00:00:00', '2023-12-01 00:00:00'),
(17, 17, '王浩然', 'https://api.dicebear.com/9.x/shapes/svg?seed=wanghaoran', '0', '1993-01-15', '13078901234', 'wanghaoran@example.com', '交互设计师，专注于数字产品的交互体验设计。具备丰富的用户研究经验和交互设计技能，善于通过原型设计和用户测试验证设计方案。曾参与多个大型互联网产品的交互设计工作，在移动端交互设计方面有深入研究。', 'INTERACTION_DESIGNER', '["figma", "axure_rp", "user_research", "wireframing", "user_testing"]', 5, 'EMPLOYED', '福州市鼓楼区', NULL, 11, NULL, NULL, 'https://wanghaoran.interaction', '{"dribbble": "https://dribbble.com/wanghaoran", "github": "https://github.com/wanghaoran"}', '0', '2022-11-01 00:00:00', '2023-12-01 00:00:00'),
(18, 18, '李雅琴', 'https://api.dicebear.com/9.x/shapes/svg?seed=liyaqin', '1', '1990-06-22', '13189012345', 'liyaqin@example.com', '视觉设计师，专注于品牌视觉设计和视觉传达。拥有丰富的视觉设计经验，善于通过色彩、字体、图形等视觉元素传达品牌价值。在品牌标识设计、视觉系统构建、创意广告设计等方面有专业能力。', 'VISUAL_DESIGNER', '["photoshop", "illustrator", "visual_design", "color_theory", "typography"]', 7, 'FREELANCER', '济南市历下区', NULL, NULL, NULL, NULL, 'https://liyaqin.visual', '{"behance": "https://behance.net/liyaqin", "pinterest": "https://pinterest.com/liyaqin"}', '0', '2022-01-15 00:00:00', '2023-12-01 00:00:00'),
(19, 19, '陈志豪', 'https://api.dicebear.com/9.x/shapes/svg?seed=chenzhihao', '0', '1992-12-08', '13290123456', 'chenzhihao@example.com', '插画师，专注于商业插画和概念设计。具备扎实的美术功底和独特的创作风格，作品风格多样，能够根据不同项目需求调整创作方向。在游戏美术、品牌插画、概念设计等领域有丰富经验，作品多次获得业内认可。', 'ILLUSTRATOR', '["illustrator", "photoshop", "illustration", "character_design", "scene_design"]', 5, 'FREELANCER', '郑州市金水区', NULL, NULL, NULL, NULL, 'https://chenzhihao.art', '{"instagram": "https://instagram.com/chenzhihao", "artstation": "https://artstation.com/chenzhihao"}', '0', '2022-07-01 00:00:00', '2023-12-01 00:00:00'),
(20, 20, '赵雅琪', 'https://api.dicebear.com/9.x/shapes/svg?seed=zhaoyaqi', '1', '1991-09-14', '13301234567', 'zhaoyaqi@example.com', '平面设计师，专注于印刷品设计和数字媒体设计。在杂志排版、海报设计、宣传册制作等方面有丰富经验。善于运用色彩和排版创造视觉冲击力，作品风格现代简约，注重信息传达的清晰性和美观性。', 'GRAPHIC_DESIGNER', '["photoshop", "illustrator", "graphic_design", "layout_design", "print_design"]', 6, 'EMPLOYED', '长沙市岳麓区', NULL, 12, NULL, NULL, 'https://zhaoyaqi.graphic', '{"behance": "https://behance.net/zhaoyaqi", "linkedin": "https://linkedin.com/in/zhaoyaqi"}', '0', '2022-04-01 00:00:00', '2023-12-01 00:00:00');
INSERT INTO `des_education` (`education_id`, `designer_id`, `school`, `degree`, `major`, `start_date`, `end_date`, `is_current`, `description`, `gpa`, `ranking`, `total_students`, `status`, `create_time`, `update_time`) VALUES
(1, 1, '中国美术学院', '硕士', '设计学', '2015-09-01', '2018-06-30', 0, '专业方向：数字媒体艺术，研究方向：交互设计与用户体验。主要课程包括用户体验设计、交互设计方法、视觉传达设计等。', 3.80, 5, 48, '0', '2015-09-01 00:00:00', '2018-06-30 00:00:00'),
(2, 1, '浙江大学', '学士', '工业设计', '2011-09-01', '2015-06-30', 0, '主修课程：设计基础、人机交互、产品设计、计算机辅助设计。参与多项设计竞赛并获奖，具备扎实的设计理论基础。', 3.60, 8, 120, '0', '2011-09-01 00:00:00', '2015-06-30 00:00:00'),
(3, 2, '清华大学美术学院', '学士', '视觉传达设计', '2012-09-01', '2016-06-30', 0, '主修课程：平面设计、品牌设计、包装设计、广告设计等。在校期间多次获得设计奖学金，作品在多个展览中展出。', 3.90, 2, 60, '0', '2012-09-01 00:00:00', '2016-06-30 00:00:00'),
(4, 3, '北京电影学院', '学士', '动画设计', '2014-09-01', '2018-06-30', 0, '主修课程：三维动画、角色设计、场景设计、动画导演等。毕业作品《未来城市》获得学院优秀毕业作品奖。', 3.70, 6, 80, '0', '2014-09-01 00:00:00', '2018-06-30 00:00:00'),
(5, 4, '同济大学', '硕士', '工业设计', '2015-09-01', '2018-06-30', 0, '研究方向：交互设计与用户体验。参与多个产品设计项目，在人机交互和用户研究方面有深入学习。', 3.80, 3, 40, '0', '2015-09-01 00:00:00', '2018-06-30 00:00:00'),
(6, 4, '华中科技大学', '学士', '工业设计', '2011-09-01', '2015-06-30', 0, '主修课程：产品设计、人机工程学、设计心理学、计算机辅助设计等。', 3.50, 15, 90, '0', '2011-09-01 00:00:00', '2015-06-30 00:00:00'),
