INSERT INTO `des_work_experience` (`experience_id`, `designer_id`, `company`, `position`, `start_date`, `end_date`, `is_current`, `description`, `location`, `industry`, `status`, `create_time`, `update_time`) VALUES
(1, 1, '腾讯科技有限公司', '高级 UI/UX 设计师', '2022-03-01', NULL, 1, '负责腾讯社交产品的用户体验设计，主导产品界面改版与优化，建立设计规范与组件库。参与用户研究与需求分析，提出基于数据的设计解决方案。带领团队完成多个重要项目，包括微信小程序设计规范制定、QQ音乐界面重设计等。', '深圳市南山区', '互联网', '0', '2022-03-01 00:00:00', NOW()),
(2, 1, '字节跳动', 'UI 设计师', '2020-06-01', '2022-02-28', 0, '参与短视频应用的界面设计工作，负责功能迭代与视觉优化，协助建立设计规范。与产品和开发团队紧密合作，确保设计方案的顺利实现。主要参与抖音、今日头条等产品的设计优化工作。', '北京市朝阳区', '互联网', '0', '2020-06-01 00:00:00', '2022-02-28 00:00:00'),
(3, 1, '美团', '初级 UI 设计师', '2018-07-01', '2020-05-31', 0, '负责美团外卖和美团App的界面设计工作，参与产品功能迭代和视觉优化。学习和掌握了大型互联网产品的设计流程和方法，积累了丰富的移动端设计经验。', '北京市朝阳区', '互联网', '0', '2018-07-01 00:00:00', '2020-05-31 00:00:00'),
(4, 2, '4A广告公司', '资深视觉设计师', '2021-01-01', NULL, 1, '负责品牌视觉设计和广告创意执行，为多个知名品牌提供视觉设计服务。参与品牌策略制定和视觉识别系统构建，擅长整合营销传播设计。主要服务客户包括汽车、快消、金融等行业头部企业。', '上海市静安区', '广告', '0', '2021-01-01 00:00:00', NOW()),
(5, 2, '设计工作室', '品牌设计师', '2018-03-01', '2020-12-31', 0, '在精品设计工作室负责品牌设计项目，参与从品牌策略到视觉执行的全流程工作。为中小企业和创业公司提供品牌设计服务，积累了丰富的品牌设计经验和客户沟通技巧。', '上海市徐汇区', '设计服务', '0', '2018-03-01 00:00:00', '2020-12-31 00:00:00'),
(6, 3, '游戏公司', '3D美术设计师', '2021-08-01', NULL, 1, '负责手机游戏的3D美术设计工作，包括角色建模、场景设计和动画制作。参与多款热门游戏的美术制作，在角色设计和场景构建方面有丰富经验。', '北京市海淀区', '游戏', '0', '2021-08-01 00:00:00', NOW()),
(7, 4, '阿里巴巴', '产品设计师', '2020-09-01', NULL, 1, '负责B端产品的用户体验设计，参与阿里云、钉钉等企业级产品的设计工作。专注于复杂业务场景下的用户体验优化，具备丰富的B端产品设计经验。', '杭州市西湖区', '互联网', '0', '2020-09-01 00:00:00', NOW()),
(8, 5, '腾讯', '交互设计师', '2020-07-15', NULL, 1, '负责腾讯多个产品的交互设计工作，主要参与微信、QQ等社交产品的功能迭代和用户体验优化。在移动端交互设计方面有深入研究，善于通过用户研究和数据分析优化产品体验。', '成都市高新区', '互联网', '0', '2020-07-15 00:00:00', NOW());
