(4, 2, '绿色科技公司品牌设计', '为新能源科技公司设计的完整品牌形象，包括LOGO、VI系统和品牌应用', 'image', 'https://via.placeholder.com/400x300/10b981/ffffff?text=Green+Tech+Brand', NULL, NULL, '["品牌设计", "LOGO设计", "VI系统", "绿色科技"]', 128, 1890, '1', '0', '2023-07-15 00:00:00', '2023-07-15 00:00:00'),
(5, 2, '咖啡品牌包装设计', '为精品咖啡品牌设计的系列包装，融合现代简约风格与传统咖啡文化', 'image', 'https://via.placeholder.com/400x300/f59e0b/ffffff?text=Coffee+Package', NULL, NULL, '["包装设计", "品牌设计", "咖啡", "消费品"]', 95, 1456, '0', '0', '2023-09-20 00:00:00', '2023-09-20 00:00:00'),
(6, 3, '科幻角色设计系列', '原创科幻题材角色设计，展现未来世界的多元文化和技术融合', 'image', 'https://via.placeholder.com/400x300/8b5cf6/ffffff?text=Sci-Fi+Characters', NULL, NULL, '["角色设计", "3D建模", "科幻", "概念设计"]', 312, 4567, '1', '0', '2023-05-10 00:00:00', '2023-05-10 00:00:00'),
(7, 3, '产品宣传动画', '为智能家居产品制作的3D宣传动画，展示产品功能和使用场景', 'video', 'https://via.placeholder.com/400x300/ef4444/ffffff?text=Product+Animation', NULL, NULL, '["3D动画", "产品展示", "智能家居", "宣传片"]', 178, 2890, '0', '0', '2023-11-05 00:00:00', '2023-11-05 00:00:00'),
(8, 4, '企业管理系统界面设计', '为大型企业设计的管理系统界面，注重信息架构和操作效率', 'image', 'https://via.placeholder.com/400x300/3b82f6/ffffff?text=Enterprise+UI', NULL, NULL, '["Web设计", "企业应用", "B端产品", "管理系统"]', 67, 1234, '0', '0', '2023-08-15 00:00:00', '2023-08-15 00:00:00'),
(9, 5, '移动端交互原型设计', '为金融应用设计的交互原型，展示完整的用户操作流程', 'image', 'https://via.placeholder.com/400x300/10b981/ffffff?text=Mobile+Prototype', NULL, NULL, '["交互设计", "原型设计", "移动应用", "金融产品"]', 145, 2100, '1', '0', '2023-09-10 00:00:00', '2023-09-10 00:00:00');
